import numpy as np
import pytest

from doppler.buffer import I16Buffer

_ELEM_DTYPE = np.dtype([("i", np.int16), ("q", np.int16)])

pytestmark = pytest.mark.skip(
    "required constructor parameter(s) capacity have no "
    "default; seed valid arguments to enable these checks"
)


def test_write_speaks_dp_iq16_t():
    """write() accepts the declared element, and only it."""
    obj = I16Buffer(capacity=0)
    x = np.zeros(4, dtype=_ELEM_DTYPE)
    obj.write(x)

    wrong = np.zeros(4, dtype=np.float64)
    with pytest.raises((TypeError, ValueError)):
        obj.write(wrong)


def test_write_some_speaks_dp_iq16_t():
    """write_some() accepts the declared element, and only it."""
    obj = I16Buffer(capacity=0)
    x = np.zeros(4, dtype=_ELEM_DTYPE)
    obj.write_some(x)

    wrong = np.zeros(4, dtype=np.float64)
    with pytest.raises((TypeError, ValueError)):
        obj.write_some(wrong)
